import CryptoKit
import Foundation
import Jinja
import MLXLMCommon
import MLXVLM
import ProviderCoreFoundation
import XCTest
@testable import ProviderCore

/// Parity with `Fixtures/nemotron-super-prompt-golden.json`, generated by
/// `scripts/nemotron-qualification/prompt_golden.py` from the pinned reference
/// template, tokenizer and processor. Text-level and image-count checks always
/// run; token-ID parity needs the real tokenizer through
/// `NEMOTRON_SUPER_REFERENCE_DIR` (see that directory's README).
final class NemotronSuperPromptGoldenTests: XCTestCase {
    private struct Case {
        let name: String
        let body: Data
        let addGenerationPrompt: Bool
        let prompt: String
        let tokens: [Int]
        let images: [(width: Int, height: Int, tokens: Int)]
        let expanded: [Int]?
        var isText: Bool { expanded == nil }
    }

    private struct Corpus {
        let hashes: [String: String]
        let cases: [Case]
    }

    private static func corpus() throws -> Corpus {
        var url = URL(fileURLWithPath: #filePath)
        url.deleteLastPathComponent()
        let data = try Data(contentsOf: url.appendingPathComponent("Fixtures/nemotron-super-prompt-golden.json"))
        guard case .object(let root) = try NemotronSuperOrderedJSON.parse(data),
            case .object(let reference)? = root["reference"], case .object(let pins)? = reference["sha256"],
            case .array(let cases)? = root["cases"]
        else { throw CocoaError(.coderReadCorrupt) }
        let hashes = Dictionary(uniqueKeysWithValues: pins.compactMap { key, value -> (String, String)? in
            if case .string(let text) = value { return (key, text) }
            return nil
        })
        return Corpus(hashes: hashes, cases: try cases.map(Self.decode))
    }

    private static func decode(_ value: Value) throws -> Case {
        func ints(_ value: Value?) throws -> [Int] {
            guard case .array(let items)? = value else { throw CocoaError(.coderReadCorrupt) }
            return try items.map { item in
                guard case .int(let number) = item else { throw CocoaError(.coderReadCorrupt) }
                return number
            }
        }
        guard case .object(let fields) = value, case .string(let name)? = fields["name"],
            let body = fields["body"], case .boolean(let generation)? = fields["add_generation_prompt"],
            case .string(let prompt)? = fields["prompt"]
        else { throw CocoaError(.coderReadCorrupt) }
        var bodyJSON = ""
        // Request order matters for tool schemas; re-encode without reordering.
        try NemotronSuperTemplateFilters.writeJSON(body, to: &bodyJSON, depth: 0)
        var images: [(Int, Int, Int)] = []
        if case .array(let grids)? = fields["images"] {
            for grid in grids {
                guard case .object(let g) = grid, case .int(let w)? = g["width"],
                    case .int(let h)? = g["height"], case .int(let t)? = g["tokens"]
                else { throw CocoaError(.coderReadCorrupt) }
                images.append((w, h, t))
            }
        }
        var expanded: [Int]?
        if case .array(let runs)? = fields["expanded_token_runs"] {
            expanded = try runs.flatMap { run -> [Int] in
                switch run {
                case .int(let token): return [token]
                case .array(let pair): let p = try ints(.array(pair)); return Array(repeating: p[0], count: p[1])
                default: throw CocoaError(.coderReadCorrupt)
                }
            }
        }
        return Case(name: name, body: Data(bodyJSON.utf8), addGenerationPrompt: generation,
                    prompt: prompt, tokens: try ints(fields["token_ids"]), images: images, expanded: expanded)
    }

    private static func templateBytes() throws -> Data {
        try XCTUnwrap(Data(base64Encoded: superImagePinnedTemplateBase64, options: .ignoreUnknownCharacters))
    }

    /// Same path the hook and image owner use: plan, ordered messages/tools,
    /// pinned template and controls.
    private static func render(_ fixture: Case, tokenizer: any MLXLMCommon.Tokenizer) throws -> [Int] {
        let plan = try NemotronSuperRequestPlan(body: fixture.body)
        return try NemotronSuperPromptContract.render(messages: plan.request.messages, body: fixture.body,
            declared: plan.toolPolicy.tools, controls: plan.controls, templateBytes: templateBytes(),
            tokenizer: tokenizer, addGenerationPrompt: fixture.addGenerationPrompt)
    }

    func testCorpusPinsTheContractTemplate() throws {
        let corpus = try Self.corpus()
        XCTAssertEqual(corpus.hashes["chat_template.jinja"], NemotronSuperPromptContract.templateSHA256)
        XCTAssertGreaterThanOrEqual(corpus.cases.count, 30)
        XCTAssertEqual(Set(corpus.cases.map(\.name)).count, corpus.cases.count)
    }

    /// swift-jinja with the Super filters reproduces the reference prompt text.
    func testRenderedPromptTextMatchesReference() throws {
        for fixture in try Self.corpus().cases {
            let scalars = try Self.render(fixture, tokenizer: SuperTemplateTextTokenizer())
            let text = String(String.UnicodeScalarView(scalars.compactMap { Unicode.Scalar(UInt32($0)) }))
            XCTAssertEqual(text, fixture.prompt, fixture.name)
        }
    }

    func testImageGridsAndPlaceholderExpansionMatchProcessor() throws {
        let images = try Self.corpus().cases.filter { !$0.isText }
        XCTAssertGreaterThanOrEqual(images.count, 6)
        for fixture in images {
            let counts = try fixture.images.map { image in
                try NemotronSuperImagePreprocessing.grid(width: image.width, height: image.height,
                                                         imageCount: fixture.images.count).tokens
            }
            XCTAssertEqual(counts, fixture.images.map { $0.tokens }, fixture.name)
            XCTAssertEqual(try NemotronSuperPromptContract.expandImagePlaceholders(fixture.tokens,
                featureCounts: counts, contextLength: 16384), fixture.expanded, fixture.name)
        }
    }

    func testRealTokenizerReproducesGoldenTokenIDs() async throws {
        guard let path = ProcessInfo.processInfo.environment["NEMOTRON_SUPER_REFERENCE_DIR"] else {
            throw XCTSkip("""
                set NEMOTRON_SUPER_REFERENCE_DIR to a directory holding the pinned tokenizer.json, \
                tokenizer_config.json and chat_template.jinja (scripts/nemotron-qualification/README.md)
                """)
        }
        let corpus = try Self.corpus()
        let directory = URL(fileURLWithPath: path, isDirectory: true)
        for name in ["tokenizer.json", "tokenizer_config.json", "chat_template.jinja"] {
            let digest = SHA256.hash(data: try Data(contentsOf: directory.appendingPathComponent(name)))
                .map { String(format: "%02x", $0) }.joined()
            XCTAssertEqual(digest, corpus.hashes[name], "\(name) is not the pinned reference file")
        }
        let tokenizer = try await LocalTokenizerLoader().load(from: directory)
        for fixture in corpus.cases {
            XCTAssertEqual(tokenizer.encode(text: fixture.prompt, addSpecialTokens: false), fixture.tokens,
                           "tokenizer: \(fixture.name)")
            XCTAssertEqual(try Self.render(fixture, tokenizer: tokenizer), fixture.tokens, "render: \(fixture.name)")
            guard fixture.isText else {
                // The image owner's path: request messages, template, then expansion.
                let request = try ProviderLoop.decodeOpenAIRequest(fixture.body)
                XCTAssertEqual(try NemotronSuperPromptContract.imagePrompt(messages: request.messages,
                    body: fixture.body, templateBytes: Self.templateBytes(), tokenizer: tokenizer,
                    featureCounts: fixture.images.map { $0.tokens }, contextLength: 16384),
                    fixture.expanded, "image prompt: \(fixture.name)")
                continue
            }
            let plan = try NemotronSuperRequestPlan(body: fixture.body)
            XCTAssertEqual(try plan.textPromptTokens(body: fixture.body, templateBytes: Self.templateBytes(),
                tokenizer: tokenizer, addGenerationPrompt: fixture.addGenerationPrompt), fixture.tokens, fixture.name)
        }
    }
}

/// Renders with swift-jinja exactly as swift-transformers' `applyChatTemplate`
/// builds its context, returning Unicode scalars so prompt text is observable
/// without the 17 MB tokenizer. Not a tokenizer; never used for execution.
private struct SuperTemplateTextTokenizer: MLXLMCommon.Tokenizer {
    func encode(text: String, addSpecialTokens: Bool) -> [Int] { text.unicodeScalars.map { Int($0.value) } }
    func decode(tokenIds: [Int], skipSpecialTokens: Bool) -> String { "" }
    func convertTokenToId(_ token: String) -> Int? { nil }
    func convertIdToToken(_ id: Int) -> String? { nil }
    var bosToken: String? { "<s>" }
    var eosToken: String? { "<|im_end|>" }
    var unknownToken: String? { "<unk>" }
    func applyChatTemplate(messages: [[String: any Sendable]], tools: [[String: any Sendable]]?,
                           additionalContext: [String: any Sendable]?) throws -> [Int] {
        throw MLXLMCommon.TokenizerError.missingChatTemplate
    }
    func applyChatTemplate(messages: [[String: any Sendable]], chatTemplate: String,
                           tools: [[String: any Sendable]]?, additionalContext: [String: any Sendable]?) throws -> [Int] {
        let template = try Template(normalizeSwiftJinjaTemplate(chatTemplate),
                                    with: .init(lstripBlocks: true, trimBlocks: true))
        var context: [String: Value] = ["messages": .array(try messages.map { try Value(any: $0) }),
                                        "add_generation_prompt": true]
        if let tools { context["tools"] = .array(try tools.map { try Value(any: $0) }) }
        for (key, value) in additionalContext ?? [:] { context[key] = try Value(any: value) }
        for (key, value) in ["bos_token": "<s>", "eos_token": "<|im_end|>", "unk_token": "<unk>",
                             "pad_token": "<|im_end|>"] { context[key] = .string(value) }
        return encode(text: try template.render(context), addSpecialTokens: false)
    }
}
